#[derive(Clone, Copy)]
struct StoreBrand {
    icon: &'static Icon,
    tile_bg: Option<u32>,
    ink: u32,
}

fn resolve_brand(id: &str) -> Option<StoreBrand> {
    let key = id.trim().to_ascii_lowercase();
    match key.as_str() {
        "steam" | "valve" => Some(StoreBrand {
            icon: &LOGO_STEAM,
            tile_bg: None,
            ink: 0xc5c3c0,
        }),
        "epic" | "epic games" | "epic-games" | "epicgames" | "egs" => Some(StoreBrand {
            icon: &LOGO_EPIC,
            tile_bg: Some(0x2f2d2e),
            ink: 0xffffff,
        }),
        "gog" | "gog.com" | "gog galaxy" | "gog-galaxy" => Some(StoreBrand {
            icon: &LOGO_GOG,
            tile_bg: Some(0x86328a),
            ink: 0xffffff,
        }),
        "ea" | "ea app" | "ea-app" | "electronic arts" | "origin" => Some(StoreBrand {
            icon: &LOGO_EA,
            tile_bg: Some(0xff4747),
            ink: 0xffffff,
        }),
        "ubisoft" | "ubisoft connect" | "ubisoft-connect" | "uplay" => Some(StoreBrand {
            icon: &LOGO_UBISOFT,
            tile_bg: Some(0x0f7dff),
            ink: 0xffffff,
        }),
        "battlenet" | "battle.net" | "battle-net" | "blizzard" => Some(StoreBrand {
            icon: &LOGO_BATTLENET,
            tile_bg: Some(0x148eff),
            ink: 0xffffff,
        }),
        "riot" | "riot games" | "riot-games" => Some(StoreBrand {
            icon: &LOGO_RIOT,
            tile_bg: Some(0xd13639),
            ink: 0xffffff,
        }),
        "xbox" | "xbox store" | "xbox-store" | "game pass" | "xbox game pass" => Some(StoreBrand {
            icon: &LOGO_XBOX,
            tile_bg: Some(0x107c10),
            ink: 0xffffff,
        }),
        "microsoft" | "microsoft-store" | "microsoft store" | "msstore" | "windows" => {
            Some(StoreBrand {
                icon: &LOGO_MICROSOFT,
                tile_bg: Some(0x0078d4),
                ink: 0xffffff,
            })
        }
        "amazon" | "amazon games" | "amazon-games" | "prime gaming" => Some(StoreBrand {
            icon: &LOGO_AMAZON,
            tile_bg: Some(0xff9900),
            ink: 0x000000,
        }),
        "rockstar" | "rockstar games" | "rockstar-games" => Some(StoreBrand {
            icon: &LOGO_ROCKSTAR,
            tile_bg: Some(0xfcaf17),
            ink: 0x000000,
        }),
        "itch" | "itch.io" | "itchio" => Some(StoreBrand {
            icon: &LOGO_ITCH,
            tile_bg: Some(0xfa5c5c),
            ink: 0xffffff,
        }),
        "paradox" | "paradox interactive" | "paradox-interactive" => Some(StoreBrand {
            icon: &LOGO_PARADOX,
            tile_bg: Some(0x2b4c7e),
            ink: 0xffffff,
        }),
        "roblox" => Some(StoreBrand {
            icon: &LOGO_ROBLOX,
            tile_bg: None,
            ink: 0xffffff,
        }),
        "discord" => Some(StoreBrand {
            icon: &LOGO_DISCORD,
            tile_bg: Some(0x5865f2),
            ink: 0xffffff,
        }),
        "spotify" => Some(StoreBrand {
            icon: &LOGO_SPOTIFY,
            tile_bg: None,
            ink: 0x1ed760,
        }),
        "youtube" | "youtube-music" | "youtube music" | "ytmusic" => Some(StoreBrand {
            icon: &LOGO_YOUTUBE,
            tile_bg: Some(0xff0000),
            ink: 0xffffff,
        }),
        "apple" | "apple-music" | "apple music" => Some(StoreBrand {
            icon: &LOGO_APPLE_MUSIC,
            tile_bg: Some(0xfa233b),
            ink: 0xffffff,
        }),
        _ => None,
    }
}

pub fn store_logo_icon(id: &str) -> Option<&'static Icon> {
    resolve_brand(id).map(|b| b.icon)
}

pub fn store_logo_mono(id: &str, size: f32, color: Color) -> Option<El> {
    let brand = resolve_brand(id)?;
    Some(icon(brand.icon, size).color(color))
}

pub fn store_logo(id: &str, size: f32) -> Option<El> {
    let brand = resolve_brand(id)?;
    let ink = if brand.ink == 0x000000 {
        BG
    } else if brand.ink == 0xffffff {
        FG
    } else {
        hex(brand.ink, 1.0)
    };
    if let Some(bg_hex) = brand.tile_bg {
        let mark_size = (size * 0.62).round().max(8.0);
        let radius = (size * 0.28).round();
        Some(
            el().size(size, size)
                .radius(radius)
                .continuous_corners()
                .center()
                .fill(hex(bg_hex, 1.0))
                .child(icon(brand.icon, mark_size).color(ink)),
        )
    } else {
        Some(icon(brand.icon, size).color(ink))
    }
}

pub fn store_logo_or_fallback(id: &str, size: f32) -> El {
    store_logo(id, size).unwrap_or_else(|| icon_store(size, fg_muted()))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn all_known_stores_resolve_and_rasterize() {
        let ids = [
            "steam",
            "epic",
            "gog",
            "ea",
            "ubisoft",
            "battlenet",
            "riot",
            "xbox",
            "microsoft",
            "amazon",
            "rockstar",
            "itch",
            "paradox",
            "roblox",
            "discord",
            "spotify",
            "youtube",
            "apple-music",
        ];
        for id in ids {
            let ic = store_logo_icon(id).unwrap_or_else(|| panic!("missing icon for {id}"));
            let mask = rune::text::icon_coverage(ic, 20);
            let lit = mask.iter().filter(|&&a| a > 32).count();
            assert!(lit > 10, "store logo `{id}` rasterized empty (lit={lit})");
            assert!(store_logo(id, 18.0).is_some());
            assert!(store_logo_mono(id, 16.0, FG).is_some());
        }
        assert!(store_logo("unknown-store", 16.0).is_none());
    }
}
